async function brevoAccountCheck() {
  if (!BREVO_DETECT.key) return { checked: false, valid: false, message: "no key found" };
  try {
    const res = await fetch("https://api.brevo.com/v3/account", {
      headers: { "api-key": BREVO_DETECT.key, accept: "application/json" },
    });
    const data = await res.json().catch(() => ({}));
    if (res.ok) {
      return {
        checked: true,
        valid: true,
        companyName: data?.companyName || "",
        email: data?.email || "",
        message: "Key is valid — Brevo account opened:" + (data?.email ? " " + data.email : ""),
      };
    }
    let msg = data?.message || data?.error || ("HTTP " + res.status);
    if (res.status === 401) msg = "Key is wrong/disabled (401 unauthorized) — it may be an MCP key, create a plain API key.";
    return { checked: true, valid: false, status: res.status, message: msg };
  } catch (err) {
    return { checked: true, valid: false, message: "Could not reach Brevo: " + String(err?.message || err) };
  }
}

