// Brevo पर जो sender verify है वही अपने आप चुन लें (EMAIL_FROM न दिया हो तो)
async function brevoSenders() {
  if (!BREVO_API_KEY_RESOLVED) return [];
  try {
    const res = await fetch("https://api.brevo.com/v3/senders?limit=50", {
      headers: { "api-key": BREVO_API_KEY_RESOLVED, accept: "application/json" },
    });
    if (!res.ok) return [];
    const data = await res.json().catch(() => ({}));
    const list = Array.isArray(data?.senders) ? data.senders : [];
    return list.map((x) => ({ email: String(x.email || ""), name: String(x.name || ""), active: x.active !== false }));
  } catch {
    return [];
  }
}

async function ensureSender() {
  if (EMAIL_FROM) return EMAIL_FROM;
  const list = await brevoSenders();
  const pick = list.find((x) => x.active) || list[0];
  if (pick && EMAIL_RE.test(pick.email)) {
    EMAIL_FROM = pick.email;
    EMAIL_SENDER_AUTO = pick.email;
  }
  return EMAIL_FROM;
}

/** { email: { hash, expiresAt, attempts, sentAt, sentCount } } */
const emailOtpStore = new Map();
let emailOtpDayKey = new Date().toISOString().slice(0, 10);
let emailOtpDayCount = 0;

function emailToday() {
  const key = new Date().toISOString().slice(0, 10);
  if (key !== emailOtpDayKey) {
    emailOtpDayKey = key;
    emailOtpDayCount = 0;
  }
  return emailOtpDayCount;
}

function normalizeEmail(raw) {
  const e = String(raw || "").trim().toLowerCase();
  if (e.length < 6 || e.length > 120) return "";
  if (!/^[^\s@]+@[^\s@]+\.[a-zA-Z]{2,}$/.test(e)) return "";
  return e;
}

// CAPTCHA + OTP anti-pumping guard. Maps are process-local; use shared persistent storage
// (e.g. Redis/Supabase RPC) for multi-instance production deployments.
const TURNSTILE_SITE_KEY = String(process.env.TURNSTILE_SITE_KEY || "").trim();
const TURNSTILE_SECRET_KEY = String(process.env.TURNSTILE_SECRET_KEY || "").trim();
const OTP_GUARD = { phone: new Map(), ip: new Map(), prefix: new Map(), blocks: new Map(), unresolved: new Map(), issued: new Map(), failures: new Map() };
function requestIp(req) {
  const forwarded = String(req.headers["x-forwarded-for"] || "").split(",").map((value) => value.trim()).filter(Boolean);
  // Cloudflare supplies its own client IP. Otherwise use the right-most proxy entry;
  // the left-most XFF value can be supplied by the caller and must not be trusted.
  return String(req.headers["cf-connecting-ip"] || forwarded[forwarded.length - 1] || req.socket.remoteAddress || "unknown").trim() || "unknown";
}
function pruneTimes(map, key, now, windowMs) {
  const kept = (map.get(key) || []).filter((t) => now - t < windowMs);
  map.set(key, kept);
  return kept;
}
function blockedOtp(res, waitMs, reason) {
  const seconds = Math.max(1, Math.ceil(waitMs / 1000));
  res.setHeader("Retry-After", String(seconds));
  res.setHeader("X-OTP-Block-Reason", reason);
  res.status(429).json({ ok: false, error: "बहुत ज़्यादा OTP अनुरोध हुए हैं। कुछ समय बाद फिर कोशिश करें।", retryAfterSeconds: seconds });
}
async function verifyTurnstile(req, token) {
  if (!TURNSTILE_SITE_KEY || !TURNSTILE_SECRET_KEY) return { ok: false, unavailable: true };
  const value = String(token || "").trim();
  if (!value || value.length > 4096) return { ok: false };
  try {
    const body = new URLSearchParams({ secret: TURNSTILE_SECRET_KEY, response: value, remoteip: requestIp(req) });
    const response = await fetch("https://challenges.cloudflare.com/turnstile/v0/siteverify", { method: "POST", headers: { "Content-Type": "application/x-www-form-urlencoded" }, body });
    const result = await response.json();
    const host = String(result.hostname || "").toLowerCase();
    const allowedHosts = new Set([String(req.hostname || "").toLowerCase(), ...APP_ORIGINS.map((origin) => { try { return new URL(origin).hostname.toLowerCase(); } catch { return ""; } })]);
    return { ok: Boolean(result.success) && (!host || allowedHosts.has(host)), hostname: host };
  } catch { return { ok: false }; }
}
async function protectOtpIssue(req, res, target, phone = "") {
  const captcha = await verifyTurnstile(req, req.body?.captchaToken);
  if (captcha.unavailable) {
    res.status(503).json({ ok: false, error: "CAPTCHA is not configured. Set TURNSTILE_SITE_KEY and TURNSTILE_SECRET_KEY on the server." });
    return false;
  }
  if (!captcha.ok) {
    res.status(403).json({ ok: false, code: "captcha_failed", error: "Security check failed or expired. Complete it again." });
    return false;
  }
  const now = Date.now();
  const ip = requestIp(req);
  const key = phone || String(target || "").toLowerCase();
  const ipBlock = OTP_GUARD.blocks.get(`ip:${ip}`);
  const phoneBlock = phone && OTP_GUARD.blocks.get(`phone:${phone}`);
  const prefixBlock = phone && OTP_GUARD.blocks.get(`prefix:${phone.slice(0, 4)}`);
  const activeBlock = [ipBlock, phoneBlock, prefixBlock].find((until) => until && until > now);
  if (activeBlock) { blockedOtp(res, activeBlock - now, "temporary_block"); return false; }
  const ipTimes = pruneTimes(OTP_GUARD.ip, ip, now, 15 * 60 * 1000);
  if (ipTimes.length >= 8) { blockedOtp(res, ipTimes[0] + 15 * 60 * 1000 - now, "ip_rate_limit"); return false; }
  if (phone) {
    const phoneTimes = pruneTimes(OTP_GUARD.phone, phone, now, 10 * 60 * 1000);
    if (phoneTimes.length && now - phoneTimes[phoneTimes.length - 1] < 60 * 1000) { blockedOtp(res, 60 * 1000 - (now - phoneTimes[phoneTimes.length - 1]), "resend_cooldown"); return false; }
    if (phoneTimes.length >= 3) { blockedOtp(res, phoneTimes[0] + 10 * 60 * 1000 - now, "phone_rate_limit"); return false; }
    const prefix = phone.slice(0, 4);
    const prefixTimes = pruneTimes(OTP_GUARD.prefix, prefix, now, 24 * 60 * 60 * 1000);
    if (prefixTimes.length >= 10) { OTP_GUARD.blocks.set(`prefix:${prefix}`, now + 24 * 60 * 60 * 1000); blockedOtp(res, 24 * 60 * 60 * 1000, "prefix_abuse"); return false; }
  }
  // Reserve limits before provider calls to avoid concurrent requests bypassing limits.
  ipTimes.push(now);
  if (phone) { pruneTimes(OTP_GUARD.phone, phone, now, 10 * 60 * 1000).push(now); pruneTimes(OTP_GUARD.prefix, phone.slice(0, 4), now, 24 * 60 * 60 * 1000).push(now); }
  req.otpGuard = { ip, key, phone, at: now };
  return true;
}
function markOtpIssued(req, otpKey) {
  const info = req.otpGuard;
  if (!info) return;
  const now = Date.now();
  for (const [key, entry] of OTP_GUARD.issued) if (now - entry.at >= 24 * 60 * 60 * 1000) OTP_GUARD.issued.delete(key);
  const issuedKey = otpKey || info.key;
  const list = OTP_GUARD.unresolved.get(info.ip) || [];
  list.push({ key: issuedKey, phone: info.phone, at: info.at });
  OTP_GUARD.unresolved.set(info.ip, list.filter((item) => Date.now() - item.at < 24 * 60 * 60 * 1000));
  OTP_GUARD.issued.set(issuedKey, { ip: info.ip, phone: info.phone, at: info.at });
  if (info.phone) {
    const unresolvedPhone = [...OTP_GUARD.issued.values()].filter((item) => item.phone === info.phone && Date.now() - item.at < 24 * 60 * 60 * 1000).length;
    const prefix = info.phone.slice(0, 4);
    const unresolvedPrefix = [...OTP_GUARD.issued.values()].filter((item) => item.phone?.startsWith(prefix) && Date.now() - item.at < 24 * 60 * 60 * 1000).length;
    if (unresolvedPhone >= 5) OTP_GUARD.blocks.set(`phone:${info.phone}`, Date.now() + 60 * 60 * 1000);
    if (unresolvedPrefix >= 10) OTP_GUARD.blocks.set(`prefix:${prefix}`, Date.now() + 24 * 60 * 60 * 1000);
  }
  if (OTP_GUARD.unresolved.get(info.ip).length >= 8) OTP_GUARD.blocks.set(`ip:${info.ip}`, Date.now() + 60 * 60 * 1000);
}
function resolveOtpIssued(key) {
  const info = OTP_GUARD.issued.get(key);
  if (!info) return;
  OTP_GUARD.issued.delete(key);
  const list = OTP_GUARD.unresolved.get(info.ip) || [];
  OTP_GUARD.unresolved.set(info.ip, list.filter((item) => item.key !== key));
}
function recordOtpFailure(key, ip) {
  const now = Date.now();
  for (const [label, value] of [[`phone:${key}`, key], [`ip:${ip}`, ip]]) {
    const times = pruneTimes(OTP_GUARD.failures, label, now, 15 * 60 * 1000);
    times.push(now);
    if (times.length >= 10) OTP_GUARD.blocks.set(label, now + 60 * 60 * 1000);
  }
}
app.get("/api/security/turnstile-widget", (req, res) => {
  const parentOrigin = String(req.query?.parentOrigin || "");
  let parsed;
  try { parsed = new URL(parentOrigin); } catch { return res.status(400).send("Invalid parent origin"); }
  const permitted = new Set([...APP_ORIGINS, "https://app.wrongchat.local"].map((origin) => { try { return new URL(origin).origin; } catch { return ""; } }));
  if (parsed.origin !== parentOrigin || !permitted.has(parsed.origin)) return res.status(403).send("Parent origin is not allowed");
  res.removeHeader("X-Frame-Options");
  res.setHeader("Content-Security-Policy", `frame-ancestors ${parsed.origin}`);
  if (!TURNSTILE_SITE_KEY) return res.status(503).type("html").send("<!doctype html><meta name=viewport content='width=device-width'><p style='font:14px system-ui;color:#b91c1c'>CAPTCHA configuration required.</p><script>parent.postMessage({type:'wc-turnstile-error',message:'CAPTCHA is not configured on the server.'}," + JSON.stringify(parentOrigin) + ")</script>");
  res.type("html").send(`<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><script src="https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit" async defer></script></head><body style="margin:0;font:14px system-ui"><div id="captcha"></div><script>
  const target=${JSON.stringify(parentOrigin)};
  function fail(){parent.postMessage({type:'wc-turnstile-error',message:'CAPTCHA could not load. Check internet and server keys.'},target)}
  function renderCaptcha(){try{turnstile.render('#captcha',{sitekey:${JSON.stringify(TURNSTILE_SITE_KEY)},callback:function(token){parent.postMessage({type:'wc-turnstile-token',token:token},target)},'expired-callback':function(){parent.postMessage({type:'wc-turnstile-error',message:'CAPTCHA expired. Complete it again.'},target)},'error-callback':fail})}catch(e){fail()}}
  let tries=0;const poll=setInterval(function(){if(window.turnstile){clearInterval(poll);renderCaptcha()}else if(++tries>45){clearInterval(poll);fail()}},200);
  </script></body></html>`);
});

function emailOtpHash(email, code) {
  return crypto.createHmac("sha256", OTP_SECRET).update(`mail|${email}|${code}`).digest("hex");
}

function emailOtpTokenValid(email, token) {
  try {
    const [issuedRaw, sig] = String(token || "").split(".");
    const issued = Number(issuedRaw);
    if (!Number.isSafeInteger(issued) || !sig || issued > Date.now() + 30000 || Date.now() - issued > EMAIL_OTP_TTL_MS) return false;
    const expect = crypto.createHmac("sha256", OTP_SECRET).update(`mail|${email}|${issued}`).digest("hex").slice(0, 32);
    if (sig.length !== expect.length) return false;
    return crypto.timingSafeEqual(Buffer.from(sig, "utf8"), Buffer.from(expect, "utf8"));
  } catch {
    return false;
  }
}

/**
 * 🔑 STATELESS OTP (v3.9.2)
 * कोड ईमेल + 10-मिनट की खिड़की से बनता है — कहीं सेव करने की ज़रूरत नहीं।
 * इसलिए सर्वर restart / नई deploy / दूसरा instance होने पर भी कोड जाँच में पास होगा।
 */
// 🔐 समय-आधारित कोड — हर सेकंड नया, पर 10 मिनट तक मान्य (restart-proof)
const OTP_SECONDS_RANGE = Math.ceil(EMAIL_OTP_TTL_MS / 1000); // 600 सेकंड

function secondOtpCode(email, sec) {
  const digest = crypto
    .createHmac("sha256", OTP_SECRET)
    .update(`otps|${email}|${sec}`)
    .digest("hex");
  const n = parseInt(digest.slice(0, 10), 16) % 1000000;
  return String(n).padStart(6, "0");
}

/** अभी का कोड (हर सेकंड अलग) */
function freshOtpCode(email) {
  return secondOtpCode(email, Math.floor(Date.now() / 1000));
}

/** क्या यह कोड पिछले 10 मिनट में कभी बना था? (restart के बाद भी हाँ) */
function isRecentOtpCode(email, code) {
  const nowSec = Math.floor(Date.now() / 1000);
  for (let i = 0; i <= OTP_SECONDS_RANGE; i += 1) {
    if (secondOtpCode(email, nowSec - i) === code) return true;
  }
  return false;
}

